UPDATE memory_tags
SET aliases = (
    SELECT COALESCE(array_agg(DISTINCT x), ARRAY[]::text[]) FROM (
        SELECT unnest(survivor.aliases) x
        FROM memory_tags survivor WHERE survivor.id = #{survivorId}
        UNION
        SELECT unnest(loser.aliases) x
        FROM memory_tags loser WHERE loser.id = #{loserId}
    ) sub
), updated_at = now()
WHERE id = #{survivorId}

DELETE FROM memory_entry_coverage
WHERE tag_id = #{loser}
  AND (entry_id, project_id, user_id) IN (
      SELECT entry_id, project_id, user_id FROM memory_entry_coverage WHERE tag_id = #{survivor}
  );
UPDATE memory_entry_coverage SET tag_id = #{survivor} WHERE tag_id = #{loser}

DELETE FROM memory_summary_coverage
WHERE tag_id = #{loser}
  AND (turn_id, project_id, user_id) IN (
      SELECT turn_id, project_id, user_id FROM memory_summary_coverage WHERE tag_id = #{survivor}
  );
UPDATE memory_summary_coverage SET tag_id = #{survivor} WHERE tag_id = #{loser}
